import {getPluginOptionName} from 'editor_tiny/options';
import {pluginName} from './common';

const layoutName = getPluginOptionName(pluginName, 'layout');

/**
 * Registers the options of this plugin.
 *
 * @param {TinyMCE} editor
 */
export const register = (editor) => {
    editor.options.register(layoutName, {
        processor: 'string',
        "default": '',
    });
};

/**
 * The layout given by the server, already validated there.
 *
 * @param {TinyMCE} editor
 * @returns {Object|null} Null keeps the Moodle default.
 */
export const getLayout = (editor) => {
    const json = editor.options.get(layoutName);
    if (!json) {
        return null;
    }
    try {
        const layout = JSON.parse(json);
        return Array.isArray(layout.toolbar) ? layout : null;
    } catch (e) {
        return null;
    }
};
